 private static void add(String es,String en,String fr,String de,String it,String pt){TR.put(es,new String[]{es,en,fr,de,it,pt});}
 public static String t(Context c,String key){return t(key,getEffectiveLanguage(c));}
 public static String t(String key,String lang){if(key==null)return null;String[] a=TR.get(key);if(a==null)return key;if("es".equals(lang))return a[0];if("fr".equals(lang))return a[2];if("de".equals(lang))return a[3];if("it".equals(lang))return a[4];if("pt".equals(lang))return a[5];return a[1];}
 public static String translateDynamic(Context c,String s){if(s==null)return null;String lang=getEffectiveLanguage(c);if("Electric Vs\nCombustion Calculator".equals(s)){if("es".equals(lang))return "Eléctrico vs\nCombustión";if("fr".equals(lang))return "Électrique vs\nCombustion";if("de".equals(lang))return "Elektro vs\nVerbrenner";if("it".equals(lang))return "Elettrico vs\nCombustione";if("pt".equals(lang))return "Elétrico vs\nCombustão";return "Electric vs\nCombustion";}String langValue=s;String[] lines=langValue.split("\\n",-1);if(lines.length>1){StringBuilder out=new StringBuilder();for(int i=0;i<lines.length;i++){if(i>0)out.append('\n');out.append(translateDynamic(c,lines[i]));}return out.toString();}for(Map.Entry<String,String[]> e:TR.entrySet()){String[] a=e.getValue();for(String x:a)if(x!=null&&x.equals(s))return t(e.getKey(),lang);}return s;}
 public static void translateViews(Activity a){translateView(a,a.findViewById(android.R.id.content));}
 private static void translateView(Context c,View v){if(v instanceof TextView){TextView tv=(TextView)v;CharSequence cs=tv.getText();if(cs!=null){String s=cs.toString(),n=translateDynamic(c,s);if(!s.equals(n))tv.setText(n);if(isHeaderTitle(s)||isHeaderTitle(n)){tv.setGravity(Gravity.CENTER);tv.setTextAlignment(View.TEXT_ALIGNMENT_CENTER);tv.setMaxLines(2);tv.setIncludeFontPadding(false);}}}if(v instanceof ViewGroup){ViewGroup g=(ViewGroup)v;for(int i=0;i<g.getChildCount();i++)translateView(c,g.getChildAt(i));}}
 private static boolean isHeaderTitle(String s){if(s==null)return false;return s.equals("EV Charge Calculator")||s.equals("Calculateur de recharge EV")||s.equals("EV-Laderechner")||s.equals("Calcolatore di ricarica EV")||s.equals("Calculadora de carregamento EV")||s.equals("Electric Vs\nCombustion Calculator")||s.equals("Electric vs\nCombustion")||s.equals("Eléctrico vs\nCombustión")||s.equals("Électrique vs\nCombustion")||s.equals("Elektro vs\nVerbrenner")||s.equals("Elettrico vs\nCombustione")||s.equals("Elétrico vs\nCombustão");}
